// Generates src/lib/themes-data.ts from the built-in themes in the themes/ folder (project root).
// Usage: node tools/gen-themes.mjs. A test (v03.test) checks that the generated file matches themes/.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const dir = path.resolve(root, "..", "themes");
const ORDER = ["predeterminado", "minimalista", "cupertino", "retro", "alto-contraste"];
const themes = ORDER.map((id) => JSON.parse(fs.readFileSync(path.join(dir, id + ".json"), "utf8")));
const out = `// GENERATED by tools/gen-themes.mjs from themes/*.json. Do not edit by hand.\nimport type { ThemeDef } from "./theme";\n\nexport const BUILTIN_THEMES: ThemeDef[] = ${JSON.stringify(themes, null, 1)};\n`;
fs.writeFileSync(path.join(root, "src", "lib", "themes-data.ts"), out);
console.log(`Built-in themes: ${themes.length} → src/lib/themes-data.ts`);
